#!/usr/bin/env bash
# Week-2b: momentum halting + auto-calibrated NTC. Run from TokenGuard repo root.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing Week-2b (momentum halt + auto-calibration)..."
decode "scripts/ntc_week2_controller.py" << 'B64EOF'

B64EOF
echo ""; echo "Installed. Run:"; echo "  python scripts/ntc_week2_controller.py --model Qwen/Qwen3-1.7B --benchmark gsm8k --limit 150 --max-tokens 1024 --tp-size 1"